(() => {
    if (!selectedAsset) {
      return "Unassigned";
    }

    const fromAssignment = getActiveAssignmentForAsset(
      selectedAsset.id
    )?.employeeName?.trim();
    if (fromAssignment) {
      return fromAssignment;
    }

    const fromAsset = selectedAsset.assignedEmployeeName?.trim();
    return fromAsset || "Unassigned";
  })
